SET NOCOUNT ON
GO

CREATE TABLE [TBS003] (
  [UFESIG] char(2) COLLATE Latin1_General_BIN CONSTRAINT [DF_TBS003_UFESIG_TBS003]  DEFAULT '' NOT NULL,
  [MUNCOD] int CONSTRAINT [DF_TBS003_MUNCOD_TBS003]  DEFAULT 0 NOT NULL,
  [MUNNOM] char(35) COLLATE Latin1_General_BIN CONSTRAINT [DF_TBS003_MUNNOM_TBS003]  DEFAULT '' NULL
)
ON [PRIMARY]
GO

CREATE NONCLUSTERED INDEX [ITBS0033] ON [TBS003]
  ([UFESIG], [MUNNOM])
ON [PRIMARY]
GO

CREATE NONCLUSTERED INDEX [ITBS0034] ON [TBS003]
  ([MUNNOM])
ON [PRIMARY]
GO

ALTER TABLE [TBS003]
ADD PRIMARY KEY CLUSTERED ([UFESIG], [MUNCOD])
ON [PRIMARY]
GO

